#include <bits/stdc++.h>
using namespace std;

int main() {
	int n;
	cin >> n;
	vector a(n * 4 - 1, 0);
	for(auto &v : a) cin >> v;
	cout << accumulate(a.begin(), a.end(), 0, [](int x, int y) { return x ^ y; }) << '\n';
	return 0;
}
